const promoCodeStats = `-- name: PromoCodeStats :one
SELECT
    (SELECT count(*) FROM promo_redemptions r WHERE r.promo_code_id = $1 AND r.status = 'confirmed')::int AS uses,
    (SELECT count(*) FROM promo_redemptions r WHERE r.promo_code_id = $1 AND r.status = 'applied')::int AS pending,
    (SELECT coalesce(sum(r.amount), 0) FROM promo_redemptions r WHERE r.promo_code_id = $1 AND r.status = 'confirmed')::bigint AS discount_total,
    (SELECT coalesce(sum(b.total_amount), 0) FROM promo_redemptions r JOIN bookings b ON b.id = r.booking_id
       WHERE r.promo_code_id = $1 AND r.status = 'confirmed')::bigint AS revenue,
    (SELECT count(DISTINCT r.phone) FROM promo_redemptions r WHERE r.promo_code_id = $1 AND r.status = 'confirmed')::int AS customers
`

type PromoCodeStatsRow struct {
	Uses          int32
	Pending       int32
	DiscountTotal int64
	Revenue       int64
	Customers     int32
}

func (q *Queries) PromoCodeStats(ctx context.Context, id uuid.UUID) (PromoCodeStatsRow, error) {
	row := q.db.QueryRow(ctx, promoCodeStats, id)
	var i PromoCodeStatsRow
	err := row.Scan(
		&i.Uses,
		&i.Pending,
		&i.DiscountTotal,
		&i.Revenue,
		&i.Customers,
	)
	return i, err
}

